<?php
namespace Tests\Feature;
use App\Models\User;
use App\Modules\Identity\Services\IdentitySecurity as Security;
use App\Modules\Identity\Services\Outbox;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Crypt;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Mail;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Facades\Storage;
use Illuminate\Http\UploadedFile;
use Laravel\Sanctum\Sanctum;
use PragmaRX\Google2FA\Google2FA;
use Tests\TestCase;
class IdentityCompletionTest extends TestCase {
 use RefreshDatabase;
 private function user(string $email='user@example.test'):User{return User::create(['name'=>'Fictif','email'=>$email,'password'=>'Fictional12345']);}
 private function message(User $u):string{$row=DB::table('notification_outbox')->where('user_id',$u->id)->latest('id')->first();return json_decode(Crypt::decryptString($row->encrypted_message),true)['body'];}
 private function token(User $u):string{preg_match('/token=([A-Za-z0-9]{64})/',$this->message($u),$m);return $m[1];}
 private function draft(User $u):int{Sanctum::actingAs($u);return $this->postJson('/api/v1/registration-applications')->assertCreated()->json('id');}
 public function test_verification_is_hashed_expiring_one_use_and_not_logged_in_outbox():void{$u=$this->user();Sanctum::actingAs($u);$this->postJson('/api/v1/auth/email/request')->assertOk();$token=$this->token($u);$this->assertDatabaseHas('identity_tokens',['token_hash'=>hash('sha256',$token)]);$this->assertStringNotContainsString($token,DB::table('notification_outbox')->value('encrypted_message'));$this->postJson('/api/v1/auth/email/verify',['token'=>$token,'purpose'=>'verify'])->assertOk();$this->assertNotNull($u->fresh()->email_verified_at);$this->postJson('/api/v1/auth/email/verify',['token'=>$token,'purpose'=>'verify'])->assertUnprocessable();}
 public function test_resend_invalidates_previous_verification_and_expired_links_fail():void{$u=$this->user();Security::email($u);$old=$this->token($u);Security::email($u);$fresh=$this->token($u);$this->postJson('/api/v1/auth/email/verify',['token'=>$old,'purpose'=>'verify'])->assertUnprocessable();DB::table('identity_tokens')->where('token_hash',hash('sha256',$fresh))->update(['expires_at'=>now()->subMinute()]);$this->postJson('/api/v1/auth/email/verify',['token'=>$fresh,'purpose'=>'verify'])->assertUnprocessable();}
 public function test_forgot_is_generic_reset_revokes_sessions_and_cannot_replay():void{$u=$this->user();$u->createToken('old');$known=$this->postJson('/api/v1/auth/forgot-password',['email'=>$u->email])->assertOk()->json();$unknown=$this->postJson('/api/v1/auth/forgot-password',['email'=>'absent@example.test'])->assertOk()->json();$this->assertSame($known,$unknown);$payload=['token'=>$this->token($u),'password'=>'NewFictional12345','password_confirmation'=>'NewFictional12345'];$this->postJson('/api/v1/auth/reset-password',$payload)->assertOk();$this->assertTrue(Hash::check('NewFictional12345',$u->fresh()->password));$this->assertSame(0,$u->tokens()->count());$this->postJson('/api/v1/auth/reset-password',$payload)->assertUnprocessable();}
 public function test_email_change_requires_password_and_verification_without_premature_identity_change():void{$u=$this->user();Sanctum::actingAs($u);$this->postJson('/api/v1/security/email',['email'=>'new@example.test','current_password'=>'wrong'])->assertUnprocessable();$this->postJson('/api/v1/security/email',['email'=>'new@example.test','current_password'=>'Fictional12345'])->assertOk();$this->assertSame('user@example.test',$u->fresh()->email);$this->postJson('/api/v1/auth/email/verify',['token'=>$this->token($u),'purpose'=>'email_change'])->assertOk();$this->assertSame('new@example.test',$u->fresh()->email);}
 public function test_mfa_enrollment_login_and_replay_protection():void{$u=$this->user();Sanctum::actingAs($u);$secret=$this->postJson('/api/v1/security/mfa/setup',['current_password'=>'Fictional12345'])->assertOk()->json('secret');$this->assertNotSame($secret,$u->fresh()->mfa_secret);$code=(new Google2FA())->oathTotp($secret,(int)floor(now()->timestamp/30));$this->postJson('/api/v1/security/mfa/confirm',['mfa_code'=>$code])->assertOk();$this->app['auth']->forgetGuards();$this->postJson('/api/v1/auth/login',['email'=>$u->email,'password'=>'Fictional12345'])->assertUnprocessable();$this->postJson('/api/v1/auth/login',['email'=>$u->email,'password'=>'Fictional12345','mfa_code'=>$code])->assertUnprocessable();$this->travel(31)->seconds();$code=(new Google2FA())->oathTotp($secret,(int)floor(now()->timestamp/30));$this->postJson('/api/v1/auth/login',['email'=>$u->email,'password'=>'Fictional12345','mfa_code'=>$code])->assertOk();}
 public function test_inactive_account_cannot_reuse_token():void{$u=$this->user();$token=$u->createToken('test')->plainTextToken;$u->forceFill(['is_active'=>false])->save();$this->withToken($token)->getJson('/api/v1/me')->assertForbidden();}
 public function test_local_inbox_is_owner_scoped_and_unavailable_in_production():void{$u=$this->user();Security::email($u);$id=DB::table('notification_outbox')->value('id');Sanctum::actingAs($u);$this->getJson('/api/v1/notifications/'.$id.'/preview')->assertNotFound();config(['socle.local_inbox'=>true]);$this->getJson('/api/v1/notifications/'.$id.'/preview')->assertOk()->assertJsonPath('simulation',true);Sanctum::actingAs($this->user('other@example.test'));$this->getJson('/api/v1/notifications/'.$id.'/preview')->assertNotFound();$this->app->detectEnvironment(fn()=>'production');Sanctum::actingAs($u);$this->getJson('/api/v1/notifications/'.$id.'/preview')->assertNotFound();}
 public function test_log_mail_is_simulation_and_smtp_errors_are_retryable_without_secret_logs():void{$u=$this->user();Security::email($u);config(['mail.default'=>'log']);$this->assertSame(1,Outbox::dispatch()['simulated']);$this->assertDatabaseHas('notification_outbox',['status'=>'simulated','sent_at'=>null]);Security::email($u);config(['mail.default'=>'smtp']);Mail::shouldReceive('raw')->once()->andThrow(new \RuntimeException('Secret SMTP text'));$this->assertSame(1,Outbox::dispatch()['failed']);$this->assertDatabaseHas('notification_outbox',['status'=>'failed','attempts'=>1]);}
 public function test_outbox_idempotency_and_success_status():void{$u=$this->user();Outbox::push($u->id,'same-event','Titre','Texte');Outbox::push($u->id,'same-event','Titre','Texte');$this->assertDatabaseCount('notification_outbox',1);config(['mail.default'=>'smtp']);Mail::fake();$this->assertSame(1,Outbox::dispatch()['sent']);$this->assertDatabaseHas('notification_outbox',['status'=>'sent','attempts'=>1]);}
 public function test_draft_is_partial_owner_scoped_versioned_and_submission_requires_verified_complete_fields():void{$u=$this->user();$id=$this->draft($u);$this->postJson('/api/v1/registration-applications')->assertOk()->assertJsonPath('id',$id);$this->patchJson('/api/v1/registration-applications/'.$id,['version'=>1,'officine_name'=>'Fictive'])->assertOk();$this->patchJson('/api/v1/registration-applications/'.$id,['version'=>1,'city'=>'stale'])->assertConflict();$this->postJson('/api/v1/registration-applications/'.$id.'/submit',['version'=>2,'consent'=>true])->assertForbidden();$u->forceFill(['email_verified_at'=>now()])->save();Sanctum::actingAs($u);$this->postJson('/api/v1/registration-applications/'.$id.'/submit',['version'=>2,'consent'=>true])->assertUnprocessable();$this->patchJson('/api/v1/registration-applications/'.$id,['version'=>2,'phone'=>'+2290100000000','city'=>'Porto-Novo','address'=>'Fictif','applicant_function'=>'Titulaire','department'=>'Ouémé','contact_name'=>'Fictif'])->assertOk();$this->postJson('/api/v1/registration-applications/'.$id.'/submit',['version'=>3,'consent'=>true])->assertOk();$this->postJson('/api/v1/registration-applications/'.$id.'/submit',['version'=>3,'consent'=>true])->assertConflict();$this->assertDatabaseHas('officines',['id'=>$id,'status'=>'pending']);}
 public function test_internal_comments_and_private_pieces_do_not_leak():void{Storage::fake('local');$u=$this->user();$id=$this->draft($u);$this->postJson('/api/v1/registration-applications/'.$id.'/comments',['message'=>'Interne','is_internal'=>true])->assertForbidden();$review=$this->user('reviewer@example.test');$review->forceFill(['is_platform_admin'=>true])->save();Sanctum::actingAs($review);$this->getJson('/api/v1/registration-applications/'.$id.'/comments')->assertNotFound();DB::table('officines')->where('id',$id)->update(['status'=>'corrections_requested']);$this->postJson('/api/v1/registration-applications/'.$id.'/comments',['message'=>'Note privée','is_internal'=>true])->assertCreated();Sanctum::actingAs($u);$this->getJson('/api/v1/registration-applications/'.$id.'/comments')->assertJsonCount(0,'data');$this->post('/api/v1/registration-applications/'.$id.'/documents',['file'=>UploadedFile::fake()->create('piece.pdf',10,'application/pdf'),'type'=>'Facultatif'],['Accept'=>'application/json'])->assertCreated();$doc=DB::table('application_documents')->first();$this->get('/api/v1/registration-applications/'.$id.'/documents/'.$doc->id,['Accept'=>'application/json'])->assertOk()->assertHeader('X-Content-Type-Options','nosniff');Sanctum::actingAs($this->user('stranger@example.test'));$this->getJson('/api/v1/registration-applications/'.$id.'/documents')->assertNotFound();$this->getJson('/api/v1/registration-applications/'.$id.'/documents/'.$doc->id)->assertNotFound();}
 public function test_google_is_closed_without_credentials_and_does_not_trust_browser_claims():void{config(['services.google.client_id'=>null]);$this->getJson('/api/v1/auth/providers')->assertJsonPath('google_enabled',false);$this->postJson('/api/v1/auth/google/start',['email'=>'fake@example.test','sub'=>'forged'])->assertStatus(503);$this->postJson('/api/v1/auth/google/exchange',['code'=>str_repeat('x',64)])->assertUnprocessable();}
 public function test_google_state_pkce_existing_email_collision_and_callback_replay():void{config(['services.google.client_id'=>'client','services.google.client_secret'=>'test-secret','services.google.redirect'=>'https://example.test/api/v1/auth/google/callback']);$this->user();$start=$this->postJson('/api/v1/auth/google/start')->assertOk();parse_str(parse_url($start->json('url'),PHP_URL_QUERY),$query);$this->assertSame('S256',$query['code_challenge_method']);$cookie=$start->headers->getCookies()[0]->getValue();Http::fake(['oauth2.googleapis.com/*'=>Http::response(['access_token'=>'provider-access']),'openidconnect.googleapis.com/*'=>Http::response(['sub'=>'google-stable-id','email'=>'user@example.test','email_verified'=>true])]);$callback='/api/v1/auth/google/callback?'.http_build_query(['state'=>$query['state'],'code'=>'provider-code']);$this->withUnencryptedCookie('bestpharma_oauth',$cookie)->get($callback)->assertRedirect(config('socle.frontend_url').'/google-callback#error=google_failed');$this->assertDatabaseCount('auth_identities',0);$this->withUnencryptedCookie('bestpharma_oauth',$cookie)->get($callback)->assertRedirect(config('socle.frontend_url').'/google-callback#error=google_failed');Http::assertSentCount(2);}
}
